from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_groups = []
    stack = []
    close_map = {')': '(', ']': '[', '}': '{'}

    for char in paren_string:
        if char in close_map.values():
            stack.append(char)
        elif char in close_map.keys():
            if stack and close_map[char] == stack[-1]:
                stack.pop()
            else:
                paren_groups.append(''.join(stack[::-1]) + char)
                stack = []

    return paren_groups
