from collections import Counter

def factorize(n: int) -> List[int]:
    factors = []
    for i in range(2, int(n**0.5) + 1):
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count > 0:
            factors.append(i)
    factors.append(n)
    return Counter(factors).most_common()
