def file_name_check(file_name):
    # Check if the file name contains more than three digits
    if any(char.isdigit() for char in file_name):
        return 'No'

    # Check if the file name contains exactly one dot '.'
    if '.' not in file_name:
        return 'No'

    # Check if the substring before the dot is not empty and starts with a letter
    if not (file_name.startswith(r'_\w') and any(char.isalpha() for char in file_name[:file_name.find('.')])):
        return 'No'

    # Check if the substring after the dot is one of the valid extensions
    if file_name.split('.')[-1] not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'
