def solve(s):
    """Reverse the case of letters and keep non-letter characters as is."""
    # Check if the string contains any letters
    if not any(char.isalpha() for char in s):
        # If no letters, reverse the string
        return s[::-1]
    else:
        # Otherwise, reverse the case of letters
        return ''.join(char.swapcase() for char in s if char.isalpha())
